-- 017 (2026-10-18): public Texas expert resources directory. Public read, admin-only write. Contacts verified against each org's official site.
-- Rollback: 017_texas_resources_down.sql
begin;
create table if not exists public.texas_resources (
  slug text primary key, name text not null, kind text not null check (kind in ('organization','public inquiry')),
  specialty text[] not null default '{}', region text not null default 'Texas', contact text, contact_url text, availability text,
  source_url text not null, last_verified date not null, sort int not null default 100, active boolean not null default true, updated_at timestamptz not null default now());
alter table public.texas_resources enable row level security;
drop policy if exists "texas resources read" on public.texas_resources;
create policy "texas resources read" on public.texas_resources for select using (active);
drop policy if exists "texas resources admin write" on public.texas_resources;
create policy "texas resources admin write" on public.texas_resources for all to authenticated using (public.is_admin()) with check (public.is_admin());
grant select on public.texas_resources to anon, authenticated;
insert into public.texas_resources (slug,name,kind,specialty,region,contact,contact_url,availability,source_url,last_verified,sort) values
('thc-archeology','Texas Historical Commission, Archeology Division','organization',array['artifacts'],'Texas (statewide)','archeology@thc.texas.gov · 512-463-6096','https://thc.texas.gov/preserve/archeology-texas/regional-archeology','Regional archeologists respond to public inquiries about archeological sites and artifacts; use the regional map to reach your area''s archeologist.','https://thc.texas.gov/preserve/archeology-texas/regional-archeology','2026-10-18'::date,10),
('tasn','Texas Archeological Stewardship Network (THC)','public inquiry',array['artifacts'],'Texas (statewide)','tasn@thc.texas.gov · 512-463-6043','https://thc.texas.gov/preserve/archeology-texas/texas-archeological-stewardship-network','Volunteer avocational stewards who record sites and private artifact collections and assist THC archeologists.','https://thc.texas.gov/preserve/archeology-texas/texas-archeological-stewardship-network','2026-10-18'::date,20),
('tas','Texas Archeological Society','organization',array['artifacts'],'Texas (statewide)','tasoffice@txarch.org · 512-265-5324 · online contact form','https://www.txarch.org/contact','The contact form routes questions to the business office, a committee or a regional director. Regional chapters below.','https://www.txarch.org/contact','2026-10-18'::date,30),
('has','Houston Archeological Society (TAS chapter)','organization',array['artifacts'],'Houston area','info@txhas.org','https://www.txhas.org/contact-us.html','Monthly meetings on the third Thursday, 6:00–7:45 pm, Trini Mendenhall Community Center, Houston.','https://www.txhas.org/contact-us.html','2026-10-18'::date,40),
('ntas','North Texas Archeological Society (TAS chapter)','organization',array['artifacts'],'Dallas–Fort Worth','info@ntxas.org · 817-381-8117','https://ntxas.org/contact-us','Hybrid monthly meetings on the second Thursday, 7:00–8:30 pm (UNT Health Science Center, Fort Worth, or Zoom).','https://ntxas.org/contact-us','2026-10-18'::date,50),
('tsnhm','Texas Science & Natural History Museum (UT Austin)','public inquiry',array['fossils','minerals'],'Austin / Central Texas','TMMCollections@austin.utexas.edu','https://sciencemuseum.utexas.edu/exhibit/discovery-center/','In-person fossil identification with a paleontologist by appointment, Tuesday–Saturday 1–4 pm (email to request; regular admission applies). Educational IDs only: no authentications or appraisals.','https://sciencemuseum.utexas.edu/exhibit/discovery-center/','2026-10-18'::date,60),
('dps','Dallas Paleontological Society','organization',array['fossils'],'Dallas–Fort Worth (about 100 miles)','Hotline 817-355-4693 · Fossil Bureau of Investigation: fbi@dallaspaleo.org','https://www.dallaspaleo.org/Contact','The Fossil Bureau of Investigation helps identify fossils and investigate finds, generally within about 100 miles of Dallas.','https://www.dallaspaleo.org/FBI','2026-10-18'::date,70),
('psoa','Paleontological Society of Austin','organization',array['fossils'],'Austin / Central Texas','Officer contacts on the society''s contact page','https://www.austinpaleo.org/contacts.html','Monthly meetings, usually the third Tuesday at 7:00 pm (Austin Gem and Mineral Society, 6719 Burnet Lane). The public is invited; bring finds for identification.','https://www.austinpaleo.org/meeting.html','2026-10-18'::date,80),
('tarl','Texas Archeological Research Laboratory (UT Austin)','organization',array['artifacts'],'Texas (statewide)','Official contact page','https://liberalarts.utexas.edu/tarl/about-us.html','A research collections facility, not a public identification service: TARL does not authenticate or appraise artifacts for private citizens. Research access by appointment.','https://liberalarts.utexas.edu/tarl/about-us.html','2026-10-18'::date,90),
('lll','Lubbock Lake Landmark (Museum of Texas Tech University)','organization',array['artifacts','fossils'],'Lubbock / South Plains','lubbock.lake@ttu.edu · 806-742-1116','https://www.depts.ttu.edu/museumttu/LLL/StaffContact.html','General information, research and field opportunities through the Landmark office.','https://www.depts.ttu.edu/museumttu/LLL/StaffContact.html','2026-10-18'::date,100),
('smu-arc','SMU Archaeology Research Collections','organization',array['artifacts'],'Dallas','SMU Anthropology main office 214-768-2684','https://www.smu.edu/dedman/academics/departments/anthropology/about/contact','Research collection; access by appointment.','https://people.smu.edu/arcsmu/about-us/','2026-10-18'::date,110),
('cbbs','Center for Big Bend Studies (Sul Ross State University)','organization',array['artifacts'],'Big Bend / Trans-Pecos','cbbs@sulross.edu · 432-837-8179','https://cbbs.sulross.edu/','Research center for the archeology and history of the Big Bend region.','https://cbbs.sulross.edu/','2026-10-18'::date,120)
on conflict (slug) do update set name=excluded.name, kind=excluded.kind, specialty=excluded.specialty, region=excluded.region, contact=excluded.contact, contact_url=excluded.contact_url,
  availability=excluded.availability, source_url=excluded.source_url, last_verified=excluded.last_verified, sort=excluded.sort, updated_at=now();
commit;
